parameters.jsCode:
let r = $json;

if (typeof r.body === 'string') {
  try {
    r = JSON.parse(r.body);
  } catch (e) {}
}

const raw = r?.choices?.[0]?.message?.content || '';

let cleaned = String(raw)
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let out = null;

try {
  out = JSON.parse(cleaned);
} catch (e) {
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');

  if (start >= 0 && end > start) {
    try {
      out = JSON.parse(cleaned.slice(start, end + 1));
    } catch (x) {}
  }
}

const intents = [
  'price',
  'schedule',
  'job_placement',
  'complaint',
  'spam',
  'other'
];

const languages = [
  'bn',
  'en',
  'mixed'
];

const words = String(out?.suggested_reply || '')
  .trim()
  .split(/\s+/)
  .filter(Boolean)
  .length;

// Get routing thresholds from Set Node Config
const hotThreshold = Number($json.hot_threshold ?? 7);
const mediumThreshold = Number($json.medium_threshold ?? 4);

const valid =
  !!out &&
  intents.includes(out.intent) &&
  languages.includes(out.language) &&
  Number.isInteger(out.lead_score) &&
  out.lead_score >= 1 &&
  out.lead_score <= 10 &&
  typeof out.summary === 'string' &&
  typeof out.suggested_reply === 'string' &&
  words <= 80 &&
  typeof out.needs_human === 'boolean';

let route = 'FALLBACK';

if (valid) {
  // Spam gets log-only route
  if (out.intent === 'spam') {
    route = 'SPAM';

  // Complaint or human assistance goes to support
  } else if (
    out.intent === 'complaint' ||
    out.needs_human === true
  ) {
    route = 'SUPPORT';

  // Hot lead
  } else if (out.lead_score >= hotThreshold) {
    route = 'HOT';

  // Medium lead
  } else if (out.lead_score >= mediumThreshold) {
    route = 'MEDIUM';

  // Low lead
  } else {
    route = 'LOW';
  }
}

// Route reason for Google Sheets Logs
let reason = '';

if (!valid) {
  reason = 'Invalid AI JSON output';

} else if (route === 'SPAM') {
  reason = 'Spam inquiry';

} else if (route === 'SUPPORT') {
  reason = 'Complaint or human assistance required';

} else if (route === 'HOT') {
  reason = `High lead score (${hotThreshold}-10)`;

} else if (route === 'MEDIUM') {
  reason = `Medium lead score (${mediumThreshold}-${hotThreshold - 1})`;

} else if (route === 'LOW') {
  reason = `Low lead score (1-${mediumThreshold - 1})`;

} else {
  reason = 'Fallback route';
}

// Token usage
const usage = r?.usage || {};

const promptTokens = Number(usage.prompt_tokens || 0);
const completionTokens = Number(usage.completion_tokens || 0);

const totalTokens = Number(
  usage.total_tokens ||
  (promptTokens + completionTokens)
);

// Estimated token cost
// Current estimate configured for this workflow
const inputCostPerMillion = 0.20;
const outputCostPerMillion = 0.75;

const estimatedTokenCost =
  (promptTokens / 1000000 * inputCostPerMillion) +
  (completionTokens / 1000000 * outputCostPerMillion);

return [
  {
    json: {
      ...$json,

      // AI result
      ai_raw: raw,
      ai_output: out,
      json_valid: valid,

      // Token usage
      prompt_tokens: promptTokens,
      completion_tokens: completionTokens,
      total_tokens: totalTokens,

      // Estimated cost
      estimated_token_cost:
        Number(estimatedTokenCost.toFixed(8)),

      // Routing
      route: route,
      reason: reason
    }
  }
];
